'use strict';
function photoSrc(p){const src=typeof p==='string'?p:p?.src;return /^photos\/[a-zA-Z0-9._-]+$/.test(src||'')?src:'#'}
const lookupLot=id=>[...catalog.listings,...state.custom].find(l=>l.id===id);
const dateCO=t=>t?new Date(t).toLocaleString('es-CO',{timeZone:'America/Bogota',day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}):'Sin consulta registrada';
const originalPhotoCard=card;
card=function(l){let markup=originalPhotoCard(l);const photos=(l.photos||[]).filter(p=>photoSrc(p)!=='#');if(photos.length){markup=markup.replace('<div class="cardvisual">',`<div class="cardvisual has-photo"><img class="listing-cover" data-property-photo src="${esc(photoSrc(photos[0]))}" alt="Fotografía publicada de ${esc(l.title)}" loading="lazy" decoding="async"><button class="photo-open" data-detail="${esc(l.id)}" aria-label="Ver fotos y ficha de ${esc(l.title)}"></button><span class="photo-count">▧ ${photos.length} foto${photos.length===1?'':'s'}</span>`).replace('PAISAJE CONCEPTUAL · NO ES FOTO DEL LOTE','FOTO DEL ANUNCIO · '+esc(l.source));}markup=markup.replace('<div class="cardactions">',`<div class="card-meta"><span class="link-state">${l.link_check?.http_status===200?'↗ Enlace consultado':'↗ Fuente original'}</span><span>${l.geo?'⌖ Punto publicado':'⌖ Sector por confirmar'}</span></div><div class="cardactions">`);return markup;};
const viewer=document.createElement('dialog');viewer.id='photoViewer';viewer.setAttribute('aria-label','Visor de fotografías del anuncio');document.body.append(viewer);let activeGallery=null;
function openPhoto(id,index=0){const l=lookupLot(id),ps=(l?.photos||[]).filter(p=>photoSrc(p)!=='#');if(!ps.length)return;index=(index+ps.length)%ps.length;activeGallery={id,index};viewer.innerHTML=`<div class="lightbox-top"><span>${esc(l.title)}</span><button class="round" data-photo-close aria-label="Cerrar visor de fotos">×</button></div><div class="lightbox-stage"><button class="photo-arrow" data-photo-step="-1" aria-label="Foto anterior">‹</button><img data-property-photo src="${esc(photoSrc(ps[index]))}" alt="Foto ${index+1} de ${ps.length} de ${esc(l.title)}"><button class="photo-arrow" data-photo-step="1" aria-label="Foto siguiente">›</button></div><div class="lightbox-bottom"><span>${index+1} / ${ps.length}</span><a href="${esc(safeUrl(l.url))}" target="_blank" rel="noopener">Fotografías del anunciante · abrir fuente ↗</a></div>`;if(!viewer.open)viewer.showModal()}
const detailWithHistory=details;
details=function(id){detailWithHistory(id);const l=lookupLot(id);if(!l)return;const body=$('#modalBody');body.classList.add('rich-detail');const ps=(l.photos||[]).filter(p=>photoSrc(p)!=='#');const gallery=document.createElement('section');gallery.className='gallery-section';gallery.id='propertyPhotos';gallery.innerHTML=ps.length?`<div class="property-gallery" aria-label="Fotos del anuncio, desliza para recorrer">${ps.map((p,i)=>`<button data-view-photo="${esc(id)}" data-photo-index="${i}" aria-label="Ampliar foto ${i+1} de ${ps.length}"><img data-property-photo src="${esc(photoSrc(p))}" alt="Foto publicada ${i+1} de ${esc(l.title)}" ${i?'loading="lazy"':''} decoding="async"><span class="gallery-zoom">↗</span></button>`).join('')}</div><div class="gallery-foot"><span>Fotos del anunciante · ${ps.length} disponibles</span><span>Desliza · toca para ampliar</span></div>`:'<div class="no-photos">No se recuperaron fotos para este anuncio. Consulta la publicación original.</div>';body.prepend(gallery);
const rail=document.createElement('div');rail.className='detail-rail';rail.innerHTML='<button data-jump="propertyPhotos">Fotos</button><button data-jump="propertyContent">Anuncio</button><button data-jump="propertyMap">Mapa</button><button data-jump="propertyReview">Revisión</button>';gallery.after(rail);
const description=body.querySelector('.detailfacts')?.nextElementSibling;const content=document.createElement('section');content.id='propertyContent';content.className='publisher-content';content.innerHTML=`<div class="section-kicker">PUBLICACIÓN DEL VENDEDOR</div><h3>Lo que ofrece el anuncio</h3><p>${esc(l.source_description_summary||l.description||'Sin descripción recuperada.')}</p>${l.source_excerpt?`<details class="excerpt"><summary>Ver fragmento textual del anuncio</summary><blockquote>“${esc(l.source_excerpt)}…”</blockquote></details>`:''}<a class="source-full" href="${esc(safeUrl(l.url))}" target="_blank" rel="noopener">Leer descripción completa en el anuncio ↗</a><p class="small">Resumen fiel de la publicación. Las afirmaciones del vendedor se revisan por separado abajo.</p>`;if(description?.tagName==='P')description.replaceWith(content);else body.append(content);
const sourceLink=[...body.querySelectorAll('a')].find(a=>a.textContent==='Abrir fuente original ↗');if(sourceLink){sourceLink.textContent='Abrir anuncio original ↗';const badge=document.createElement('p');badge.className='source-live';badge.innerHTML=`<span>●</span> ${l.link_check?.http_status===200?'Página recuperada por HTTPS':'Enlace sin comprobar'} · ${esc(dateCO(l.link_check?.checked_at))}`;sourceLink.after(badge)}
const provenance=[...body.querySelectorAll('.sourcebox')][0];if(provenance){provenance.innerHTML=`<strong>Fuente y alcance de la consulta</strong><p>Fuente: ${esc(l.source)}. ${l.link_check?.http_status===200?'El enlace respondió y se recuperó la publicación.':'No se completó una consulta directa de este enlace.'} Esto no confirma que la venta continúe disponible.</p>${l.alternate_urls?.length?'<p>Referencia coincidente: '+l.alternate_urls.map(u=>`<a href="${esc(safeUrl(u))}" target="_blank" rel="noopener">Abrir otra publicación ↗</a>`).join(' · ')+'</p>':''}`;}
const reviewHeading=[...body.querySelectorAll('h3')].find(h=>h.textContent==='Tu carpeta de verificación');const sections=document.createElement('div');sections.className='property-evidence';sections.innerHTML=mapSection(l)+reviewSection(l);if(reviewHeading){reviewHeading.before(sections);reviewHeading.textContent='Tu carpeta de revisión personal'}else body.append(sections);
const copyBtn=$('#copyQuestions');if(copyBtn)copyBtn.onclick=()=>copy(`Hola, me interesa ${l.title} (${l.url}). ¿Sigue disponible y cuál es el precio actual? Para revisar la compra, ¿puede enviar matrícula inmobiliaria y oficina de registro, certificado de tradición reciente, escritura y número predial, pin/polígono y linderos, licencia de parcelación/subdivisión con resolución y planos, norma/uso del suelo, licencia de las mejoras si las hay, disponibilidad de agua/energía y permisos de saneamiento, predial y paz y salvos? Gracias.`);
};
function mapSection(l){const g=l.geo,query=encodeURIComponent([l.sector,l.city,l.department,'Colombia'].filter(Boolean).join(', '));return `<section id="propertyMap" class="property-map"><div class="section-kicker">UBICACIÓN</div><div class="map-heading"><h3>${g?'Un punto para orientarte.':'Ubicación por precisar.'}</h3><span class="pill">${g?'Punto del portal':'Solo referencia de sector'}</span></div><p>${esc(g?.note||'El anuncio no publica coordenadas utilizables. La búsqueda por sector no localiza el predio ni representa sus linderos.')}</p>${g?`<div class="map-placeholder" id="mapCanvas"><span>⌖</span><strong>${esc(l.sector||l.city)}</strong><small>${g.lat.toFixed(6)}, ${g.lon.toFixed(6)}</small><button class="primary" data-load-map="${esc(l.id)}">Mostrar mapa</button></div><div class="map-links"><a href="https://maps.apple.com/?ll=${g.lat},${g.lon}&q=${encodeURIComponent(l.title)}" target="_blank" rel="noopener">Apple Maps ↗</a><a href="https://www.openstreetmap.org/?mlat=${g.lat}&mlon=${g.lon}#map=16/${g.lat}/${g.lon}" target="_blank" rel="noopener">OpenStreetMap ↗</a></div>`:`<a class="source-full" href="https://www.google.com/maps/search/?api=1&query=${query}" target="_blank" rel="noopener">Buscar el sector como referencia ↗</a>`}<p class="small">${g?'Fuente de las coordenadas: el anuncio. La precisión no está verificada. Un pin no sustituye plano catastral, levantamiento ni visita.':'Solicita al vendedor el pin o el polígono antes de evaluar el predio en visores oficiales.'}</p></section>`;}
function reviewSection(l){const review=l.purchase_review,labels={seller_claim:'Declarado por el vendedor',pending:'Pendiente de soporte',missing_identifier:'Falta identificar el predio'};return `<section id="propertyReview" class="purchase-review"><div class="section-kicker">REVISIÓN DE COMPRA · EVIDENCIA</div><h3>Qué sabemos. Qué falta.</h3><div class="review-stats"><div><strong>0</strong><span>Documentos prediales verificados</span></div><div><strong>${(review?.items||[]).filter(i=>i.status==='seller_claim').length}</strong><span>Afirmaciones por contrastar</span></div></div><p class="small">${esc(review?.scope||'No hay documentos del predio disponibles para una verificación independiente.')}</p>${(review?.items||[]).map(i=>`<details class="review-item"><summary><span class="review-dot ${i.status==='seller_claim'?'claimed':''}"></span><span><strong>${esc(i.topic)}</strong><small>${labels[i.status]||'Pendiente'}</small></span><span class="review-chevron">⌄</span></summary><div class="review-body"><p>${esc(i.finding)}</p><div class="next-step"><span>SIGUIENTE PASO</span><p>${esc(i.next_step)}</p></div>${i.official_url?`<a href="${esc(safeUrl(i.official_url))}" target="_blank" rel="noopener">Consultar fuente oficial ↗</a>`:''}</div></details>`).join('')}<p class="review-limit">No localizar un documento no demuestra que no exista. Una mención comercial o una casilla marcada por ti no acredita un título o una licencia.</p><button data-request-docs="${esc(l.id)}" class="primary">Copiar solicitud de documentos</button></section>`;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.viewPhoto)openPhoto(b.dataset.viewPhoto,+b.dataset.photoIndex||0);if(b.hasAttribute('data-photo-close'))viewer.close();if(b.dataset.photoStep&&activeGallery)openPhoto(activeGallery.id,activeGallery.index+Number(b.dataset.photoStep));if(b.dataset.jump){document.getElementById(b.dataset.jump)?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})}if(b.dataset.requestDocs)$('#copyQuestions')?.click();if(b.dataset.loadMap){const l=lookupLot(b.dataset.loadMap),g=l?.geo;if(!g)return;loadPropertyMap(l).catch(()=>{const canvas=$('#mapCanvas');if(canvas)canvas.innerHTML='<p class="small">No se pudo cargar el mapa. Usa Apple Maps u OpenStreetMap en los enlaces inferiores.</p>'});}});
viewer.addEventListener('keydown',e=>{if(activeGallery&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();openPhoto(activeGallery.id,activeGallery.index+(e.key==='ArrowRight'?1:-1))}});
document.addEventListener('error',e=>{const img=e.target;if(img instanceof HTMLImageElement&&img.hasAttribute('data-property-photo')){img.style.opacity='0';const parent=img.closest('.cardvisual');if(parent){parent.classList.remove('has-photo');const caption=parent.querySelector('.visualcaption');if(caption)caption.textContent='Foto no disponible · abrir anuncio original'}else{const note=document.createElement('span');note.className='photo-error';note.textContent='No se pudo cargar esta foto. Consulta el anuncio original.';img.after(note)}}},true);
render();

let propertyMapInstance=null,leafletLoading=null;
function ensureLeaflet(){
 if(window.L)return Promise.resolve(window.L);
 if(leafletLoading)return leafletLoading;
 leafletLoading=new Promise((resolve,reject)=>{const css=document.createElement('link');css.rel='stylesheet';css.href='vendor/leaflet.css';document.head.append(css);const script=document.createElement('script');script.src='vendor/leaflet.js';script.onload=()=>resolve(window.L);script.onerror=reject;document.head.append(script)});
 return leafletLoading;
}
async function loadPropertyMap(l){
 const container=$('#mapCanvas');container.innerHTML='<p class="small">Cargando cartografía…</p>';
 const L=await ensureLeaflet();if(!container.isConnected)return;
 if(propertyMapInstance){propertyMapInstance.remove();propertyMapInstance=null}
 container.innerHTML='<div id="propertyLeaflet" aria-label="Mapa de referencia del punto publicado"></div>';
 const g=l.geo;propertyMapInstance=L.map('propertyLeaflet',{scrollWheelZoom:false,attributionControl:true}).setView([g.lat,g.lon],15);
 L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors'}).addTo(propertyMapInstance);
 L.circleMarker([g.lat,g.lon],{radius:8,color:'#fff',weight:3,fillColor:'#007aff',fillOpacity:1}).addTo(propertyMapInstance).bindPopup(esc(l.title)+'<br>Punto del portal · precisión no verificada.');
 propertyMapInstance.invalidateSize();
}
$('#modal').addEventListener('close',()=>{if(propertyMapInstance){propertyMapInstance.remove();propertyMapInstance=null}});
